/**
 * issue #67: generic, node-type-agnostic Temporal execution-identity wrapper
 * around `activities.js`'s `executeNode`, following the exact same seam as
 * `heartbeat.js` (see that file's docblock for the rationale): `activities.js`
 * is deliberately framework-agnostic (no `@temporalio/*` imports), so any
 * Temporal-specific behavior belongs in a wrapper composed in `worker.js`,
 * not inside `activities.js` itself.
 *
 * What this provides: a stable, deterministic "operation identity" attached
 * to every message as `msg._temporal = {workflowId, runId, activityId,
 * operationId}`, so an idempotency-aware flow/node can do the obvious thing
 * (HTTP `Idempotency-Key` header, DB `UNIQUE(operation_id)`, an external
 * API's own request-dedup key, ...) WITHOUT node-red-temporal implementing
 * any of those dedup mechanisms itself. See the runtime README's
 * "Operation identity for idempotent side effects" section.
 *
 * What this does NOT do (explicitly out of scope, see issue #67):
 *   - it does NOT make Activities exactly-once. Temporal Activities remain
 *     at-least-once (see worker.js's own at-least-once docblock and
 *     heartbeat.js's) - a worker crash mid-Activity still re-executes the
 *     node, and the RETRY of that same Activity invocation gets the SAME
 *     `operationId` (by design - see `buildTemporalMessageMetadata` below),
 *     it does not suppress the retry itself.
 *   - it does NOT add idempotency behavior to any stock/contrib node (no
 *     automatic HTTP headers, no DB query rewriting, no MQTT property
 *     injection, no dedup database). A flow author must explicitly read
 *     `msg._temporal.operationId` and use it.
 *   - it does NOT implement a Saga/compensation framework.
 *
 * `operationId` is derived ONLY from the three stable Temporal execution
 * identifiers (Workflow ID, Workflow Run ID, Activity ID) - never the
 * Activity attempt number, wall-clock time, or randomness - so it is
 * identical across every retry of the SAME Activity invocation, and
 * different for any other invocation (different node, different message,
 * or a resumed suspension, all of which already produce a different
 * deterministic Activity ID - see workflows.js's
 * `node:${nodeId}:${invocation}${isResume ? ":resume" : ""}`).
 */

"use strict";

const crypto = require("crypto");

/**
 * Pure helper: builds the small, JSON-serializable metadata object attached
 * to `msg._temporal`. Deliberately takes ONLY the three stable Temporal
 * execution identifiers - no attempt number is even accepted as an input,
 * so it can never accidentally participate in the hash.
 *
 * `operationId` is a SHA-256 hex digest of the three identifiers, joined by
 * a NUL separator (an unambiguous delimiter no legal Temporal ID may
 * contain) - compact, deterministic, and collision-resistant.
 *
 * @param {Object} identity
 * @param {string} identity.workflowId
 * @param {string} identity.runId
 * @param {string} identity.activityId
 * @returns {{workflowId: string, runId: string, activityId: string, operationId: string}}
 */
function buildTemporalMessageMetadata(identity) {
    var workflowId = identity.workflowId;
    var runId = identity.runId;
    var activityId = identity.activityId;
    var material = String(workflowId) + "\u0000" + String(runId) + "\u0000" + String(activityId);
    var operationId = crypto.createHash("sha256").update(material).digest("hex");
    return { workflowId: workflowId, runId: runId, activityId: activityId, operationId: operationId };
}

/**
 * Default production DI for reading the current Activity's execution
 * identity: `Context.current().info` from `@temporalio/activity`. Resolved
 * LAZILY (required on first call, not at module load), same convention as
 * `heartbeat.js`'s `defaultHeartbeat` - so this module never needs a live
 * Activity execution context just to be `require`d (e.g. from plain unit
 * tests), and never becomes a hard dependency of `activities.js`.
 */
function defaultGetActivityInfo() {
    var Context = require("@temporalio/activity").Context;
    return Context.current().info;
}

/**
 * Wraps `executeNode` so that every invocation's `msg` carries an
 * authoritative `_temporal` metadata object built from the CURRENT Temporal
 * Activity execution context, before delegating to the wrapped function.
 *
 * Any user-provided `msg._temporal` on the way in is NOT trusted as runtime
 * identity - it is unconditionally OVERWRITTEN here, since this runtime owns
 * that reserved property (issue #67's explicit requirement). The input's own
 * `msg` object is never mutated in place: a new object is built (shallow
 * clone of `msg`, `_temporal` overwritten) and passed through inside a new
 * `input` object, so the caller's original `input`/`input.msg` references are
 * left untouched - safe and cheap here since this is Activity-side (not
 * Workflow-side) code, but doing it via a fresh object rather than in-place
 * mutation keeps the wrapper trivially safe to call multiple times over the
 * same object without spooky-action-at-a-distance surprises in tests.
 *
 * If no live Activity execution context is available (`getActivityInfo`
 * throws or returns no `workflowExecution` - e.g. a unit test invoking the
 * registered Activity function directly, without a real Temporal Worker
 * polling loop), the wrapper is a transparent passthrough: it does not
 * fabricate a fake identity, and does not touch `msg` at all. In real
 * production use every `executeNode` Activity is scheduled by a Workflow, so
 * `workflowExecution` is always present.
 *
 * @param {function} executeNode - the framework-agnostic Activity from
 *   `activities.js`'s `createExecuteNode(...)` (or another wrapper around
 *   it, e.g. `heartbeat.js`'s).
 * @param {Object} [options]
 * @param {function} [options.getActivityInfo] - `() => Info`, DI seam.
 *   Defaults to `defaultGetActivityInfo` (real `@temporalio/activity`).
 * @returns {function(Object): Promise<Object>} metadata-attaching `executeNode`.
 */
function createTemporalMetadataExecuteNode(executeNode, options) {
    var opts = options || {};
    var getActivityInfo = opts.getActivityInfo || defaultGetActivityInfo;

    return function temporalMetadataExecuteNode(input) {
        var info;
        try {
            info = getActivityInfo();
        } catch (err) {
            info = undefined;
        }

        if (!info || !info.workflowExecution) {
            return executeNode(input);
        }

        var metadata = buildTemporalMessageMetadata({
            workflowId: info.workflowExecution.workflowId,
            runId: info.workflowExecution.runId,
            activityId: info.activityId
        });

        var msg = Object.assign({}, input && input.msg, { _temporal: metadata });
        var wrappedInput = Object.assign({}, input, { msg: msg });

        return executeNode(wrappedInput);
    };
}

module.exports = { buildTemporalMessageMetadata, createTemporalMetadataExecuteNode };
